class Solution {
    public int[] smallestSufficientTeam(String[] req_skills, List<List<String>> people) {
        int m = req_skills.length, n = people.size();
        java.util.Map<String, Integer> idx = new java.util.HashMap<>();
        for (int i = 0; i < m; i++) idx.put(req_skills[i], i);
        int[] personMask = new int[n];
        for (int i = 0; i < n; i++)
            for (String s : people.get(i))
                personMask[i] |= 1 << idx.get(s);
        long[] dp = new long[1 << m];
        java.util.Arrays.fill(dp, (1L << n) - 1);
        dp[0] = 0;
        for (int mask = 0; mask < (1 << m); mask++) {
            for (int i = 0; i < n; i++) {
                int newMask = mask | personMask[i];
                long newTeam = dp[mask] | (1L << i);
                if (Long.bitCount(newTeam) < Long.bitCount(dp[newMask]))
                    dp[newMask] = newTeam;
            }
        }
        long team = dp[(1 << m) - 1];
        int[] res = new int[Long.bitCount(team)];
        int j = 0;
        for (int i = 0; i < n; i++)
            if ((team & (1L << i)) != 0) res[j++] = i;
        return res;
    }
}
